code.C:
#include <stdio.h>

int main() {
    long long base, exp;
    if (scanf("%lld %lld", &base, &exp) == 2) {
        long long res = 1;
        for (int i = 0; i < exp; i++) res *= base;
        printf("%lld\n", res);
    }
    return 0;
}

