code.Java:
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNextLong()) {
            long base = sc.nextLong(), exp = sc.nextLong();
            long res = 1;
            for (int i = 0; i < exp; i++) res *= base;
            System.out.println(res);
        }
    }
}

